    }

    vector<long long> counts(n + 1, 0);

    for (int i = 0; i < n; ++i) {
        for (int j = i; j < n; ++j) {
            vector<int> interval_colors;
            for (int k = i; k <= j; ++k) {
                interval_colors.push_back(t[k]);
            }

            vector<int> color_freq(n + 1, 0);
            for (int color : interval_colors) {
                color_freq[color]++;
            }

            int dominant_color = -1;
