        while (first_non_zero < num_str.length() && num_str[first_non_zero] == '0') {
            first_non_zero++;
        }

        string tail_str = num_str.substr(first_non_zero);

        if (tail_str.empty()) {
            tails.insert(0);
        } else {
            try {
                long long tail = stoll(tail_str);
                tails.insert(tail);
            } catch (const std::out_of_range& oor) {

            }
        }
    }

    cout << tails.size() << endl;

    return 0;
}

