    for (int i = 0; i < n; ++i) {
      if (!piles[i].empty()) {
        game_over = false;
        break;
      }
    }
    if (game_over) break;

    // Ciel's turn
    int best_pile_ciel = -1;
    int best_card_ciel = -1;
    for (int i = 0; i < n; ++i) {
      if (!piles[i].empty()) {
        if (best_pile_ciel == -1 || piles[i][0] > best_card_ciel) {
          best_pile_ciel = i;
          best_card_ciel = piles[i][0];
        }
      }
    }
    ciel_score += piles[best_pile_ciel][0];
    piles[best_pile_ciel].erase(piles[best_pile_ciel].begin());


    if (true) {
        bool has_pile = false;
        for (int i = 0; i < n; ++i) {
           if (!piles[i].empty()) {
              has_pile = true;
              break;
           }
        }
        if (!has_pile) break;
    }


    // Jiro's turn
    int best_pile_jiro = -1;
    int best_card_jiro = -1;
