#include <algorithm>

using namespace std;

long long base_to_decimal(const vector<int>& digits, int base) {
    long long decimal = 0;
    long long power = 1;
    for (int i = digits.size() - 1; i >= 0; --i) {
        decimal += digits[i] * power;
        power *= base;
    }
    return decimal;
}

int main() {
