    vector<int> y(m);
    for (int i = 0; i < m; ++i) {
        cin >> y[i];
    }

    long long decimal_x = base_to_decimal(x, bx);
    long long decimal_y = base_to_decimal(y, by);

    if (decimal_x < decimal_y) {
        cout << "<" << endl;
    } else if (decimal_x > decimal_y) {
        cout << ">" << endl;
    } else {
        cout << "=" << endl;
    }

    return 0;
}

#include <iostream>
