#include <numeric>
#include <algorithm>

using namespace std;

int gcd(int a, int b) {
    if (b == 0) {
        return a;
    }
    return gcd(b, a % b);
}

int main() {
    int n, a, b;
    cin >> n >> a >> b;

    vector<int> arr(n);
    for (int i = 0; i < n; ++i) {
        cin >> arr[i];
    }

    long long min_cost = -1;

    // Option 1: No operations
    int current_gcd = arr[0];
    for (int i = 1; i < n; ++i) {
        current_gcd = gcd(current_gcd, arr[i]);
    }
    if (current_gcd > 1) {
        min_cost = 0;
    }

